<script setup>
import {computed,ref,watch} from 'vue'
import {workbenchRequest} from '../lib/backends'
import TaskMapView from './TaskMapView.vue'
import HistoricalTodo from './HistoricalTodo.vue'
const props=defineProps({view:String,settings:Object,workspaces:Array,members:Array,initialFilter:{type:String,default:'mine'}})
const emit=defineEmits(['navigate','openTicket','workspaceChanged','refreshSpaces','openConversation','openHistorical'])
const busy=ref(false),error=ref(''),notice=ref(''),queue=ref([]),report=ref(null),map=ref(null),filter=ref(props.initialFilter),ownerFilter=ref('')
const followups=ref({customer_results:[],materials:[],rechecks:[]})
const spaceName=ref(''),memberId=ref(''),memberRole=ref('agent')
const labels={open:'待处理',in_progress:'处理中',pending:'待跟进',resolved:'已解决'},priorities={urgent:'紧急',high:'较高',normal:'普通',low:'较低'}
const current=computed(()=>props.workspaces?.find(w=>w.id===props.settings.workspaceId))
const roleNames={agent:'当班客服',handoff:'接班同事',supervisor:'主管',knowledge:'知识维护人员'}
const time=value=>value?new Date(value).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}):'未安排'
const shown=computed(()=>queue.value.filter(t=>(filter.value==='all'||filter.value==='reopened'&&t.reopened_count>0||filter.value==='waiting'&&t.handoff_pending||filter.value==='awaiting'&&t.awaiting_me||filter.value==='returned'&&t.handoff_returned||filter.value==='mine'&&(t.owner===props.settings.userId||t.awaiting_me)&&t.status!=='resolved'||filter.value==='today'&&t.due_today||filter.value==='overdue'&&t.overdue||filter.value==='unassigned'&&t.owner==='待分派'&&t.status!=='resolved'||filter.value==='resolved'&&t.status==='resolved')&&(!ownerFilter.value||t.owner===ownerFilter.value)).sort((a,b)=>Number(b.overdue)-Number(a.overdue)||Number(b.due_today)-Number(a.due_today)||((a.due_at?Date.parse(a.due_at):Infinity)-(b.due_at?Date.parse(b.due_at):Infinity)||0)))

const visibleFollowups=computed(()=>Object.fromEntries(Object.entries(followups.value).map(([kind,items])=>[kind,items.filter(item=>{const owner=item.current_owner||item.owner;if(ownerFilter.value&&owner!==ownerFilter.value)return false;if(['mine','awaiting'].includes(filter.value)&&owner!==props.settings.userId)return false;if(filter.value==='resolved')return false;if(filter.value==='today'||filter.value==='overdue'){if(!item.due_at)return false;const day=new Date(item.due_at).toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'}),today=new Date().toLocaleDateString('sv-SE',{timeZone:'Asia/Shanghai'});return filter.value==='today'?day===today:new Date(item.due_at)<new Date()}return true}).sort((a,b)=>((a.due_at?Date.parse(a.due_at):Infinity)-(b.due_at?Date.parse(b.due_at):Infinity)||0))])))
const api=(path,method='GET',body)=>workbenchRequest(props.settings,path,method,body)
async function run(fn){if(busy.value)return;busy.value=true;error.value='';notice.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
let generation=0
async function load(){const current=++generation,target=props.view;busy.value=true;error.value='';try{let value;if(target==='todo'){const [queue,extra]=await Promise.all([api('/operations/queue?user_id='+encodeURIComponent(props.settings.userId)),api('/operations/followups?user_id='+encodeURIComponent(props.settings.userId))]);value={queue,extra}};if(target==='report')value=await api('/operations/report?user_id='+encodeURIComponent(props.settings.userId));if(target==='map')value=await api('/task-map');if(current===generation){if(target==='todo'){queue.value=value.queue.items;followups.value=value.extra};if(target==='report')report.value=value;if(target==='map')map.value=value}}catch(e){if(current===generation)error.value=e.message}finally{if(current===generation)busy.value=false}}
watch(()=>[props.view,props.settings.userId,props.settings.workspaceId],()=>{filter.value=props.initialFilter;ownerFilter.value='';load()},{immediate:true})
watch(()=>props.initialFilter,value=>filter.value=value)
async function createSpace(){await run(async()=>{const ws=await api('/workspaces','POST',{user_id:props.settings.userId,name:spaceName.value.trim()});spaceName.value='';emit('workspaceChanged',ws.id);notice.value='协作空间已创建；可添加同事后交接同一事项'})}
async function addMember(){await run(async()=>{await api('/workspaces/'+props.settings.workspaceId+'/members','POST',{user_id:props.settings.userId,member_id:memberId.value.trim(),role:memberRole.value});memberId.value='';emit('refreshSpaces');notice.value='成员已加入本机协作空间，未发送邀请通知'})}

</script>
<template>
<section class="page operations-page">
  <div v-if="error" class="notice error" role="alert">{{error}}</div><div v-if="notice" class="notice" role="status">{{notice}}</div>
  <header class="page-title"><div><h1>{{({todo:'今日待办',report:'服务概况',team:'协作空间',map:'用户任务地图'})[view]}}</h1><p>{{({todo:'先处理到期承诺，再继续其他事项。所有时间按上海时区显示。',report:'查看当前工作范围的本地事项结果，点指标进入原事项核对。',team:'成员共同处理同一事项；个人历史保留在个人记录中。',map:'从完整工作出发，展开角色、任务、异常分支与尚未满足的需求。'})[view]}}</p></div><button v-if="view!=='team'" class="secondary" :disabled="busy" @click="load">刷新{{view==='map'?'目录':'数据'}}</button></header>
  <p v-if="busy" role="status" class="source-note">正在读取…</p>
  <template v-if="view==='todo'">
    <h2 style="margin:0 0 10px">当前工作范围的待办 · {{current?.name||'个人记录'}}</h2>
    <div class="task-filters" role="group" aria-label="待办筛选"><button v-for="item in [{id:'mine',name:'分派给我'},{id:'awaiting',name:'待我接手'},{id:'waiting',name:'等待接手'},{id:'returned',name:'交接退回'},{id:'today',name:'今日到期'},{id:'overdue',name:'已逾期'},{id:'unassigned',name:'无人认领'},{id:'all',name:'全部事项'},{id:'resolved',name:'已解决'},{id:'reopened',name:'曾经重开'}]" :key="item.id" class="secondary" :class="{chosen:filter===item.id}" :aria-pressed="filter===item.id" @click="filter=item.id">{{item.name}}</button><label>负责人<select v-model="ownerFilter" aria-label="待办负责人"><option value="">全部负责人</option><option v-for="m in members" :key="m.id" :value="m.id">{{m.id}}</option><option value="待分派">待分派</option></select></label></div>
    <p class="source-note">默认查看本人未完成工作，先显示逾期和今日到期；历史结案可在“全部事项 / 已解决”查看。</p><div class="todo-summary"><span>{{shown.length}} 个工单</span><span>{{visibleFollowups.customer_results.length}} 项客户跟进</span><span>{{visibleFollowups.materials.length}} 项材料待办</span><span>{{visibleFollowups.rechecks.length}} 项知识回查</span></div>
    <section v-if="visibleFollowups.customer_results.length||visibleFollowups.materials.length||visibleFollowups.rechecks.length" class="followup-todo"><h2>客户结果、材料与知识回查</h2><p class="source-note">这些跟进独立于内部结案保留。点击回到原事项处理；知识回查结论在“知识与缺口”中登记。</p><button v-for="r in visibleFollowups.customer_results" :key="'result-'+r.conv_id" @click="emit('openConversation',r.conv_id)">客户结果 · {{r.case_title}}<small>{{r.owner}} · {{r.next_action}} · {{time(r.due_at)}}</small></button><button v-for="m in visibleFollowups.materials" :key="m.id" @click="emit('openConversation',m.conv_id)">材料 · {{m.name}} · {{m.status==='received'?'已收到待核验':'待收集'}}<small>{{m.owner}} · {{time(m.due_at)}}</small></button><button v-for="r in visibleFollowups.rechecks" :key="r.id" @click="emit('openConversation',r.conv_id)">知识回查 · {{r.case_title}}<small>{{r.current_owner}} · {{r.document_title}} v{{r.document_version}}{{r.document_current?'':' · 依据需重新核对'}}</small></button></section><div class="work-items"><button v-for="t in shown" :key="t.id" class="work-item" @click="emit('openTicket',t)"><div><span class="badge" :class="t.status">{{labels[t.status]}}</span><span class="priority" :class="t.priority">{{priorities[t.priority||'normal']}}</span><span class="due-flag" v-if="t.overdue">已逾期</span><span class="due-flag today" v-else-if="t.due_today">今日到期</span></div><h2>{{t.title}}</h2><p v-if="t.handoff_pending" class="handoff-queue">等待 {{t.handoff.candidate}} 接手 · 当前由 {{t.owner}} 负责</p><p v-else-if="t.handoff_returned" class="handoff-queue">交接已退回：{{t.handoff.decision_note}}</p><p>{{t.next_action||'尚未填写下一步行动，进入工单补齐。'}}</p><footer><span>{{t.id}} · {{t.owner}}</span><time>{{time(t.due_at)}}</time></footer></button><div v-if="!shown.length&&!busy" class="empty-detail"><div><h2>当前筛选没有待办</h2><p>可切换全部事项，或从客户反馈受理一条新事项。</p><button class="secondary" @click="emit('navigate',{view:'feedback'})">查看客户反馈</button></div></div></div>
    <HistoricalTodo :settings="settings" :disabled="busy" @open="emit('openHistorical',$event)"/>
  </template>
  <template v-if="view==='report'&&report">
    <p class="source-note">{{report.scope}} · 更新 {{time(report.as_of)}}</p><div class="business-metrics"><button v-for="m in [{key:'open_cases',label:'未结事项',view:'desk',filter:'unresolved'},{key:'due_today',label:'今日需跟进',filter:'today'},{key:'overdue',label:'已逾期工单',filter:'overdue'},{key:'unassigned',label:'无人认领',filter:'unassigned'},{key:'awaiting_acceptance',label:'等待接手',filter:'waiting'},{key:'returned_handoffs',label:'交接退回',filter:'returned'},{key:'resolved_cases',label:'本地已结案',view:'desk',filter:'resolved'},{key:'reopened',label:'累计重开次数',filter:'reopened'},{key:'knowledge_gaps',label:'未补齐知识',view:'knowledge'}]" :key="m.key" @click="emit('navigate',{view:m.view||'todo',filter:m.filter||'all'})"><span>{{m.label}}</span><strong>{{report[m.key]}}</strong><small>查看对应事项</small></button></div>
    <div class="table-wrap"><table><caption>按负责人查看未完成工作</caption><thead><tr><th>负责人</th><th>未完成工单</th><th>逾期</th></tr></thead><tbody><tr v-for="m in report.members" :key="m.id"><td>{{m.id}}</td><td>{{m.open}}</td><td>{{m.overdue}}</td></tr></tbody></table></div><details class="metric-definitions"><summary>统计口径</summary><p v-for="(value,key) in report.definitions" :key="key">{{value}}</p><p>统计当前个人或协作空间的累计本地记录。没有客户确认、满意度或真实渠道回执时，不计算客户解决率。</p></details>
  </template>
  <template v-if="view==='team'">
    <div class="team-layout"><form class="team-form" @submit.prevent="createSpace"><h2>创建本地协作空间</h2><label>空间名称<input v-model.trim="spaceName" required maxlength="200" placeholder="例如：售后客服组"/></label><button class="primary" :disabled="busy||!spaceName">创建协作空间</button><p class="source-note">创建者为本地空间主管。成员共享此空间事项；既有个人记录不会自动搬入。知识库和Olist样本仍在本机共享。</p></form><section v-if="current" class="team-form"><h2>{{current.name}} · 成员</h2><ul class="member-list"><li v-for="m in current.members" :key="m.id"><strong>{{m.id}}</strong><span>{{roleNames[m.role]}}</span></li></ul><form @submit.prevent="addMember"><label>成员标识<input v-model.trim="memberId" maxlength="200" required placeholder="填写同事在本地使用的标识"/></label><label>本地角色<select v-model="memberRole"><option value="agent">当班客服</option><option value="supervisor">主管</option><option value="knowledge">知识维护人员</option></select></label><button class="secondary" :disabled="busy||!memberId">添加成员</button></form></section><div v-else class="team-form"><h2>当前为个人记录</h2><p>可创建空间或从顶部工作范围切换已加入的空间，再进行团队分派。</p></div></div><p class="scope-note-wide">这是本机协作演示，成员标识切换不是企业登录认证；未向同事发送邀请、通知或消息。</p>
  </template>
  <TaskMapView v-if="view==='map'&&map" :map="map" @navigate="emit('navigate',$event)"/>
</section>
</template>
